int main(void){PIXELFORMATDESCRIPTOR p={0};HWND w;HDC dc;HGLRC c;int f;GLuint tex;unsigned char data[16]={51,102,153,255,51,102,153,255,51,102,153,255,51,102,153,255},px[4]={0};w=CreateWindowA("STATIC","WineMetalGL fixed texture",WS_OVERLAPPEDWINDOW,0,0,64,64,0,0,0,0);if(!w)return 11;dc=GetDC(w);p.nSize=sizeof(p);p.nVersion=1;p.dwFlags=PFD_DRAW_TO_WINDOW|PFD_SUPPORT_OPENGL;p.iPixelType=PFD_TYPE_RGBA;p.cColorBits=32;f=ChoosePixelFormat(dc,&p);if(!f||!SetPixelFormat(dc,f,&p))return 12;c=wglCreateContext(dc);if(!c||!wglMakeCurrent(dc,c))return 13;glViewport(0,0,64,64);glGenTextures(1,&tex);glBindTexture(GL_TEXTURE_2D,tex);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,2,2,0,GL_RGBA,GL_UNSIGNED_BYTE,data);glEnable(GL_TEXTURE_2D);glBegin(GL_TRIANGLES);glColor4f(1,1,1,1);glTexCoord2f(0,0);glVertex3f(-1,-1,0);glTexCoord2f(2,0);glVertex3f(3,-1,0);glTexCoord2f(0,2);glVertex3f(-1,3,0);glEnd();glReadPixels(32,32,1,1,GL_RGBA,GL_UNSIGNED_BYTE,px);printf("Fixed texture rgba=%u,%u,%u,%u error=0x%x\n",px[0],px[1],px[2],px[3],(unsigned)glGetError());if(px[0]<47||px[0]>55||px[1]<98||px[1]>106||px[2]<149||px[2]>157||px[3]<250)return 14;printf("WINEMETALGL_FIXED_TEXTURE_OK\n");SwapBuffers(dc);wglMakeCurrent(0,0);wglDeleteContext(c);ReleaseDC(w,dc);DestroyWindow(w);return 0;}
